import { Pool, neonConfig } from '@neondatabase/serverless';
import { PrismaNeon } from '@prisma/adapter-neon';
import { PrismaClient } from '@prisma/client';
import dotenv from 'dotenv';
import ws from 'ws';
import path from 'path';

// Explicitly load .env from project root
const envPath = path.resolve(__dirname, '../../.env');
console.log('Loading .env from:', envPath);
dotenv.config({ path: envPath });

neonConfig.webSocketConstructor = ws;

const connectionString = process.env.DATABASE_URL;
console.log('Direct Check: DATABASE_URL is', connectionString ? 'Defined' : 'Missing');

if (!connectionString) {
    console.error('❌ DATABASE_URL is missing. Exiting.');
    process.exit(1);
}

const pool = new Pool({ connectionString });
const adapter = new PrismaNeon(pool as any);
const prisma = new PrismaClient({ adapter });

async function main() {
    try {
        console.log('Testing connection...');
        await prisma.$connect();
        console.log('✅ Connected!');

        const tables: any[] = await prisma.$queryRaw`
            SELECT table_name 
            FROM information_schema.tables 
            WHERE table_schema = 'public'
        `;
        console.log('Tables in DB:', tables.map(t => t.table_name));
    } catch (e) {
        console.error('❌ Direct Check Failed:', e);
    } finally {
        await prisma.$disconnect();
    }
}

main();

import { Request, Response } from 'express';
import prisma from '../utils/prisma';
// import { UserStatus, Role } from '@prisma/client'; // Avoid import if causing issues

export const getPendingUsers = async (req: Request, res: Response) => {
    try {
        const users = await prisma.user.findMany({
            where: {
                status: 'PENDING',
                role: { in: ['SELLER', 'DELIVERY_PARTNER'] }
            } as any,
            select: {
                id: true,
                name: true,
                email: true,
                role: true,

                status: true,
                createdAt: true
            }
        });
        res.json(users);
    } catch (error) {
        console.error('Error fetching pending users:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

export const updateUserStatus = async (req: Request, res: Response) => {
    try {
        const { userId } = req.params;
        const { status } = req.body; // 'APPROVED' | 'REJECTED'

        if (!['APPROVED', 'REJECTED'].includes(status)) {
            return res.status(400).json({ message: 'Invalid status' });
        }

        const newStatus = status; // Just use the string

        const user = await prisma.user.update({
            where: { id: userId as string },
            data: { status: newStatus } as any
        });


        res.json({ message: `User ${status.toLowerCase()} successfully`, user });
    } catch (error) {
        console.error('Error updating user status:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

export const getDashboardStats = async (req: Request, res: Response) => {
    try {
        const totalUsers = await prisma.user.count();
        const totalProducts = await prisma.product.count();
        const totalOrders = await prisma.order.count();

        // Calculate revenue (sum of totalAmount from Orders where paymentStatus is 'PAID' or status is 'DELIVERED')
        // For simplicity, just valid orders
        const revenueAgg = await prisma.order.aggregate({
            _sum: {
                totalAmount: true
            }
        });

        res.json({
            totalUsers,
            totalProducts,
            totalOrders,
            totalRevenue: revenueAgg._sum.totalAmount || 0,
            activeSellers: await prisma.user.count({ where: { role: 'SELLER', status: 'APPROVED' } as any })
        });
    } catch (error) {
        console.error('Error fetching dashboard stats:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

export const getAllUsers = async (req: Request, res: Response) => {
    try {
        const users = await prisma.user.findMany({
            orderBy: { createdAt: 'desc' },
            select: {
                id: true,
                name: true,
                email: true,
                role: true,

                status: true,
                createdAt: true
            }
        });
        res.json(users);
    } catch (error) {
        console.error('Error fetching all users:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

import { Request, Response } from 'express';
import prisma from '../utils/prisma';
// import { UserStatus, Role } from '@prisma/client';
import { hashPassword, comparePassword } from '../utils/password';
import { generateToken } from '../utils/jwt';

// Helper to map frontend role to backend enum
const mapRoleToBackend = (role: string): any => {
    switch (role) {
        case 'buyer': return 'CUSTOMER';
        case 'seller': return 'SELLER';
        case 'delivery_man': return 'DELIVERY_PARTNER';
        default: return 'CUSTOMER'; // Default fallback
    }
};

// Helper to map backend enum to frontend role
const mapRoleToFrontend = (role: any) => {
    switch (role) {
        case 'CUSTOMER': return 'buyer';
        case 'SELLER': return 'seller';
        case 'DELIVERY_PARTNER': return 'delivery_man';
        case 'ADMIN': return 'ADMIN';
        default: return 'buyer';
    }
};

export const register = async (req: Request, res: Response) => {
    try {
        const { name, email, phone, password, shopName, role } = req.body;

        // Validation
        if (!name || !email || !password || !phone) {
            return res.status(400).json({ message: 'Please provide all fields' });
        }

        // Check existing user
        const existingUser = await prisma.user.findFirst({
            where: {
                OR: [
                    { email },
                    { phone }
                ]
            }
        });

        if (existingUser) {
            return res.status(400).json({ message: 'User with this email or phone already exists' });
        }

        // Create user
        const hashedPassword = await hashPassword(password);
        const user = await prisma.user.create({
            data: {
                name,
                email,
                phone,
                password: hashedPassword,
                shopName: role === 'seller' ? shopName : null,
                role: mapRoleToBackend(role),
                status: role === 'buyer' ? 'APPROVED' : 'APPROVED' // For demo simplicity, auto-approve all
            } as any,
        });

        // Generate Token
        const token = generateToken(user.id, user.role);

        res.status(201).json({
            message: 'User registered successfully',
            user: { id: user.id, name: user.name, email: user.email, phone: user.phone, role: mapRoleToFrontend(user.role) },
            token,
        });
    } catch (error) {
        console.error('Register Error:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

export const login = async (req: Request, res: Response) => {
    try {
        // Accept identifier (email/phone) OR email (backward compat)
        const identifier = req.body.identifier || req.body.email;
        const { password } = req.body;

        // Validation
        if (!identifier || !password) {
            return res.status(400).json({ message: 'Please provide email/phone and password' });
        }

        // Find User by Email OR Phone
        const user = await prisma.user.findFirst({
            where: {
                OR: [
                    { email: identifier },
                    { phone: identifier }
                ]
            }
        });

        if (!user) {
            return res.status(401).json({ message: 'Invalid credentials' });
        }

        // Check Password
        const isMatch = await comparePassword(password, user.password);
        if (!isMatch) {
            return res.status(401).json({ message: 'Invalid credentials' });
        }

        // Check Status

        const userStatus = user.status;
        if (userStatus && userStatus !== 'APPROVED') {
            return res.status(403).json({
                message: 'Your account is pending approval from the administrator.',
                status: userStatus
            });
        }

        // Generate Token
        const token = generateToken(user.id, user.role);

        res.status(200).json({
            message: 'Login successful',
            user: { id: user.id, name: user.name, email: user.email, phone: user.phone, role: mapRoleToFrontend(user.role) },
            token,
        });
    } catch (error) {
        console.error('Login Error:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

import { Request, Response } from 'express';
import prisma from '../utils/prisma';

export const getBanners = async (req: Request, res: Response) => {
    try {
        const banners = await prisma.banner.findMany({
            where: { isActive: true },
            orderBy: { order: 'asc' }
        });
        res.json(banners);
    } catch (error) {
        res.status(500).json({ message: 'Error fetching banners' });
    }
};

export const createBanner = async (req: Request, res: Response) => {
    try {
        const { title, description, imageUrl, ctaText, ctaLink, displayMode, order } = req.body;
        const banner = await prisma.banner.create({
            data: {
                title,
                description,
                imageUrl,
                ctaText,
                ctaLink,
                displayMode,
                order: order || 0
            }
        });
        res.status(201).json(banner);
    } catch (error) {
        res.status(500).json({ message: 'Error creating banner' });
    }
};

export const updateBanner = async (req: Request, res: Response) => {
    try {
        const { id } = req.params;
        const data = req.body;
        const banner = await prisma.banner.update({
            where: { id: String(id) },
            data
        });
        res.json(banner);
    } catch (error) {
        res.status(500).json({ message: 'Error updating banner' });
    }
};

export const deleteBanner = async (req: Request, res: Response) => {
    try {
        const { id } = req.params;
        await prisma.banner.delete({ where: { id: String(id) } });
        res.json({ message: 'Banner deleted successfully' });
    } catch (error) {
        res.status(500).json({ message: 'Error deleting banner' });
    }
};

import { Request, Response } from 'express';
import { productService } from '../services/productService';

export const getAllProducts = async (req: Request, res: Response) => {
    try {
        const { search } = req.query;
        let products;
        if (search) {
            products = await productService.searchProducts(search as string);
        } else {
            products = await productService.getAllProducts();
        }
        res.status(200).json(products);
    } catch (error) {
        console.error('Get All Products Error:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

export const getProductById = async (req: Request, res: Response) => {
    try {
        const id = req.params.id as string;
        const product = await productService.getProductById(id);
        if (!product) {
            return res.status(404).json({ message: 'Product not found' });
        }
        res.status(200).json(product);
    } catch (error) {
        console.error('Get Product By Id Error:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

export const createProduct = async (req: Request, res: Response) => {
    try {
        if (!req.user) {
            return res.status(401).json({ message: 'Unauthorized' });
        }

        const { name, description, price, category, image, images, stock, originalPrice, brand } = req.body;

        const productData = {
            name,
            description,
            price: parseFloat(price),
            category,
            image: image || (images && images.length > 0 ? images[0] : ''), // Fallback for backward compatibility
            images: images || (image ? [image] : []),
            stock: parseInt(stock) || 0,
            originalPrice: originalPrice ? parseFloat(originalPrice) : null,
            brand
        };

        const product = await productService.createProduct(productData, req.user.id);
        res.status(201).json({
            message: 'Product created successfully',
            product
        });
    } catch (error) {
        console.error('Create Product Error:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

export const updateProduct = async (req: Request, res: Response) => {
    try {
        const id = req.params.id as string;
        const { name, description, price, category, image, images, stock, originalPrice, brand, isActive } = req.body;

        const productData: Record<string, any> = {
            name,
            description,
            price: price ? parseFloat(price) : undefined,
            category,
            brand,
            isActive
        };

        if (stock !== undefined) productData.stock = parseInt(stock);
        if (originalPrice !== undefined) productData.originalPrice = parseFloat(originalPrice);
        if (images) {
            productData.images = images;
            productData.image = images.length > 0 ? images[0] : (image || '');
        } else if (image) {
            productData.image = image;
            // Don't overwrite images array if only single image passed, or maybe sync them? 
            // Better to assume frontend sends 'images' array for updates if it supports it.
        }

        // Remove undefined keys
        Object.keys(productData).forEach(key => productData[key] === undefined && delete productData[key]);

        const product = await productService.updateProduct(id, productData);
        res.status(200).json({
            message: 'Product updated successfully',
            product
        });
    } catch (error) {
        console.error('Update Product Error:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

export const deleteProduct = async (req: Request, res: Response) => {
    try {
        const id = req.params.id as string;
        await productService.deleteProduct(id);
        res.status(200).json({ message: 'Product deleted successfully' });
    } catch (error) {
        console.error('Delete Product Error:', error);
        res.status(500).json({ message: 'Internal server error' });
    }
};

