import { Request, Response, NextFunction } from 'express';

export const adminMiddleware = (req: any, res: any, next: any) => {
    // @ts-ignore
    if ((req.user as any)?.role !== 'ADMIN') {
        return res.status(403).json({ message: 'Access denied. Admin only.' });
    }
    next();
};

import prisma from './utils/prisma';
import fs from 'fs';
import path from 'path';

async function main() {
    try {
        console.log('Reading migration.sql...');
        const sqlPath = path.join(__dirname, '..', 'migration.sql');
        const sqlContent = fs.readFileSync(sqlPath, 'utf-8');

        // Split by semicolon to get individual statements
        // Filter out empty lines/comments to avoid errors
        const statements = sqlContent
            .split(';')
            .map(s => s.trim())
            .filter(s => s.length > 0);

        console.log(`Found ${statements.length} SQL statements. Executing...`);

        for (const [index, sql] of statements.entries()) {
            try {
                process.stdout.write(`Executing statement ${index + 1}... `);
                await prisma.$executeRawUnsafe(sql);
                console.log('✅');
            } catch (err: any) {
                // Ignore "already exists" errors to make it idempotent
                if (err.message && (err.message.includes('already exists') || err.message.includes('Duplicate'))) {
                    console.log('⚠️  (Already exists)');
                } else {
                    console.error('\n❌ Failed:', err.message);
                    // Continue? Or throw? Let's verify at the end.
                }
            }
        }

        console.log('\nMigration execution finished.');

        // Verify by listing tables
        const result: any[] = await prisma.$queryRaw`
            SELECT table_name 
            FROM information_schema.tables 
            WHERE table_schema = 'public'
        `;
        console.log('Tables in DB:', result.map(t => t.table_name));

    } catch (error) {
        console.error('Fatal Migration Error:', error);
    } finally {
        await prisma.$disconnect();
    }
}

main();

import prisma from '../utils/prisma';


export const orderService = {
    async createOrder(userId: string, deliveryAddress: string, items: { productId: string; quantity: number }[]) {
        if (!items || items.length === 0) {
            throw new Error('Order must contain at least one item');
        }

        // 1. Fetch products to get current prices and validate existence
        const productIds = items.map(i => i.productId);
        const products = await prisma.product.findMany({
            where: { id: { in: productIds } }
        });

        // Map for quick lookup
        const productMap = new Map(products.map(p => [p.id, p]));

        // 2. Calculate total and prepare order items
        let totalAmount = 0;
        const orderItemsData: { productId: string; quantity: number; priceAtPurchase: number }[] = [];

        for (const item of items) {
            const product = productMap.get(item.productId);
            if (!product) {
                throw new Error(`Product with ID ${item.productId} not found`);
            }

            // Check inventory (optional, skipping for now as per plan)

            totalAmount += product.price * item.quantity;
            orderItemsData.push({
                productId: item.productId,
                quantity: item.quantity,
                priceAtPurchase: product.price
            });
        }

        // Add fixed delivery/platform fees (hardcoded in frontend as 40 + 5)
        // ideally these should be config based
        totalAmount += 45;

        // 3. Create order and order items in a transaction
        return prisma.$transaction(async (tx) => {
            const order = await tx.order.create({
                data: {
                    userId,
                    totalAmount,
                    deliveryAddress,
                    status: 'PENDING',
                    items: {
                        create: orderItemsData
                    }
                },
                include: {
                    items: {
                        include: { product: true }
                    }
                }
            });

            return order;
        });
    },

    async getOrders(userId: string) {
        return prisma.order.findMany({
            where: { userId },
            include: {
                items: {
                    include: {
                        product: true
                    }
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    },

    async getOrderById(orderId: string) {
        return prisma.order.findUnique({
            where: { id: orderId },
            include: {
                items: {
                    include: {
                        product: true
                    }
                },
                user: {
                    select: { name: true, email: true }
                }
            }
        });
    },

    async updateOrderStatus(orderId: string, status: any) {
        return prisma.order.update({
            where: { id: orderId },
            data: { status }
        });
    },

    async getSellerOrders(sellerId: string) {
        // Find orders where at least one item belongs to this seller
        return prisma.order.findMany({
            where: {
                items: {
                    some: {
                        product: {
                            sellerId: sellerId
                        }
                    }
                }
            },
            include: {
                items: {
                    include: {
                        product: true
                    }
                },
                user: {
                    select: { name: true, phone: true }
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    },

    async getDeliveryOrders(deliveryManId: string) {
        return prisma.order.findMany({
            where: {
                OR: [
                    { status: 'READY_FOR_PICKUP', deliveryManId: null }, // Available pool
                    { deliveryManId: deliveryManId } // Assigned to me
                ]
            },
            include: {
                items: {
                    include: { product: true }
                },
                user: {
                    select: { name: true, phone: true }
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    },

    async assignDeliveryMan(orderId: string, deliveryManId: string) {
        return prisma.order.update({
            where: { id: orderId },
            data: {
                deliveryManId,
                status: 'PREPARING' // Or stay READY_FOR_PICKUP until picked up?
                // Let's assume assigning means they are on it.
                // Actually, if it was READY_FOR_PICKUP, it stays that way until PICKED_UP
            }
        });
    }
};

import prisma from '../utils/prisma';

export const productService = {
    async getAllProducts() {
        return prisma.product.findMany({
            where: { isActive: true },
            include: {
                seller: {
                    select: {
                        id: true,
                        name: true,
                        shopName: true
                    }
                },
                inventory: true
            }
        });
    },

    async getProductById(id: string) {
        return prisma.product.findUnique({
            where: { id },
            include: {
                seller: {
                    select: {
                        id: true,
                        name: true
                    }
                },
                inventory: true
            }
        });
    },

    async createProduct(data: any, sellerId: string) {
        return prisma.product.create({
            data: {
                ...data,
                sellerId,
                inventory: {
                    create: {
                        quantity: data.stock || 0,
                        warehouseId: 'default'
                    }
                }
            },
            include: {
                inventory: true
            }
        });
    },

    async updateProduct(id: string, data: any) {
        return prisma.product.update({
            where: { id },
            data
        });
    },

    async deleteProduct(id: string) {
        // Soft delete
        return prisma.product.update({
            where: { id },
            data: { isActive: false }
        });
    },

    async searchProducts(query: string) {
        return prisma.product.findMany({
            where: {
                isActive: true,
                OR: [
                    { name: { contains: query, mode: 'insensitive' } },
                    { description: { contains: query, mode: 'insensitive' } },
                    { category: { contains: query, mode: 'insensitive' } }
                ]
            },
            include: {
                seller: {
                    select: { id: true, name: true }
                }
            }
        });
    }
};

