export const AdminApprovals = () => {
    // const { token } = useAuthStore(); // Handled by api interceptor
    const { addToast } = useToast();
    const [pendingUsers, setPendingUsers] = useState<PendingUser[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const fetchPendingUsers = async () => {
        try {
            const response = await api.get('/admin/pending-users');
            setPendingUsers(response.data);
        } catch (error) {
            console.error(error);
            addToast('Error fetching pending users', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleStatusUpdate = async (userId: string, status: 'APPROVED' | 'REJECTED') => {
        try {
            await api.put(`/admin/users/${userId}/status`, { status });

            addToast(`User ${status.toLowerCase()} successfully`, 'success');
            setPendingUsers(prev => prev.filter(u => u.id !== userId));
        } catch (error) {
            addToast('Error updating status', 'error');
        }
    };

    useEffect(() => {
        fetchPendingUsers();
    }, []);

    const getRoleIcon = (role: string) => {
        switch (role) {
            case 'SELLER': return <Store className="h-5 w-5 text-purple-600" />;
            case 'DELIVERY_PARTNER': return <Truck className="h-5 w-5 text-blue-600" />;
            default: return <User className="h-5 w-5 text-gray-600" />;
        }
    };

    if (isLoading) {
        return (
            <div className="flex justify-center p-12">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
            </div>
        );
    }

    if (pendingUsers.length === 0) {
        return (
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-12 text-center">
                <div className="mx-auto h-12 w-12 text-gray-400 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                    <Check className="h-6 w-6" />
                </div>
                <h3 className="text-lg font-medium text-gray-900">All caught up!</h3>
                <p className="mt-1 text-gray-500">No pending approvals at the moment.</p>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="px-6 py-4 border-b border-gray-200">
                <h2 className="text-lg font-semibold text-gray-900">Pending Approvals</h2>
            </div>
            <ul className="divide-y divide-gray-200">
                {pendingUsers.map((user) => (
                    <li key={user.id} className="px-6 py-4 flex items-center justify-between hover:bg-gray-50 transition-colors">
                        <div className="flex items-center gap-4">
                            <div className="h-10 w-10 bg-gray-100 rounded-full flex items-center justify-center">
                                {getRoleIcon(user.role)}
                            </div>
                            <div>
                                <p className="text-sm font-medium text-gray-900">{user.name}</p>
                                <p className="text-sm text-gray-500">{user.email}</p>
                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800 mt-1">
                                    {user.role.replace('_', ' ')}
                                </span>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <button
                                onClick={() => handleStatusUpdate(user.id, 'APPROVED')}
                                className="p-2 bg-green-50 text-green-600 rounded-full hover:bg-green-100 transition-colors"
                                title="Approve"
                            >
                                <Check className="h-5 w-5" />
                            </button>
                            <button
                                onClick={() => handleStatusUpdate(user.id, 'REJECTED')}
                                className="p-2 bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
                                title="Reject"
                            >
                                <X className="h-5 w-5" />
                            </button>
                        </div>
                    </li>
                ))}
            </ul>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { Upload, X, Image as ImageIcon, Loader2 } from 'lucide-react';
import { useToast } from '../../context/ToastContext';
import api from '../../lib/api';

interface ImageUploadProps {
    onImageUploaded: (url: string) => void;
    currentImage?: string;
    label?: string;
}

export const ImageUpload: React.FC<ImageUploadProps> = ({ onImageUploaded, currentImage, label = "Product Image" }) => {
    const [preview, setPreview] = useState<string | null>(currentImage || null);
    const [isDragging, setIsDragging] = useState(false);
    const [isUploading, setIsUploading] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const { addToast } = useToast();

    const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            await uploadFile(file);
        }
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDrop = async (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const file = e.dataTransfer.files?.[0];
        if (file) {
            await uploadFile(file);
        }
    };

    const uploadFile = async (file: File) => {
        if (!file.type.startsWith('image/')) {
            addToast('Please upload an image file', 'error');
            return;
        }

        setIsUploading(true);
        const formData = new FormData();
        formData.append('image', file);

        try {
            const response = await api.post('/upload', formData, {
                headers: {
                    'Content-Type': 'multipart/form-data',
                },
            });

            const data = response.data;

            // Construct full URL including backend host
            const fullUrl = `http://localhost:5000${data.imageUrl}`;
            setPreview(fullUrl);
            onImageUploaded(fullUrl);
            addToast('Image uploaded successfully', 'success');
        } catch (error: any) {
            addToast(error.message, 'error');
        } finally {
            setIsUploading(false);
        }
    };

    const handleRemove = () => {
        setPreview(null);
        onImageUploaded('');
        if (fileInputRef.current) {
            fileInputRef.current.value = '';
        }
    };

    return (
        <div className="w-full">
            <label className="block text-sm font-medium text-gray-700 mb-2">{label}</label>

            <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileSelect}
                accept="image/*"
                className="hidden"
            />

            {preview ? (
                <div className="relative rounded-2xl overflow-hidden group aspect-video bg-gray-100 border border-gray-200">
                    <img src={preview} alt="Preview" className="w-full h-full object-cover" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4">
                        <button
                            type="button"
                            onClick={() => fileInputRef.current?.click()}
                            className="p-2 bg-white/90 rounded-full hover:bg-white transition-colors text-gray-900"
                            title="Change Image"
                        >
                            <Upload className="w-5 h-5" />
                        </button>
                        <button
                            type="button"
                            onClick={handleRemove}
                            className="p-2 bg-red-500/90 rounded-full hover:bg-red-500 transition-colors text-white"
                            title="Remove Image"
                        >
                            <X className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            ) : (
                <div
                    onClick={() => fileInputRef.current?.click()}
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={handleDrop}
                    className={`
                        relative w-full aspect-video rounded-2xl border-2 border-dashed transition-all cursor-pointer flex flex-col items-center justify-center gap-4
                        ${isDragging ? 'border-primary bg-primary/5' : 'border-gray-300 hover:border-primary hover:bg-gray-50'}
                    `}
                >
                    {isUploading ? (
                        <>
                            <Loader2 className="w-10 h-10 text-primary animate-spin" />
                            <p className="text-sm text-gray-500 font-medium">Uploading...</p>
                        </>
                    ) : (
                        <>
                            <div className={`p-4 rounded-full ${isDragging ? 'bg-primary/10' : 'bg-gray-100'}`}>
                                <ImageIcon className={`w-8 h-8 ${isDragging ? 'text-primary' : 'text-gray-400'}`} />
                            </div>
                            <div className="text-center">
                                <p className="text-sm font-medium text-gray-900">
                                    Click to upload or drag and drop
                                </p>
                                <p className="text-xs text-gray-500 mt-1">
                                    SVG, PNG, JPG or GIF (max. 5MB)
                                </p>
                            </div>
                        </>
                    )}
                </div>
            )}
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { Upload, X, Loader2 } from 'lucide-react';
import { useToast } from '../../context/ToastContext';
import api from '../../lib/api';

interface MultiImageUploadProps {
    onImagesUploaded: (urls: string[]) => void;
    currentImages?: string[];
    label?: string;
    maxFiles?: number;
}

export const MultiImageUpload: React.FC<MultiImageUploadProps> = ({
    onImagesUploaded,
    currentImages = [],
    label = "Product Images",
    maxFiles = 5
}) => {
    const [previews, setPreviews] = useState<string[]>(currentImages);
    const [isDragging, setIsDragging] = useState(false);
    const [isUploading, setIsUploading] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const { addToast } = useToast();

    const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = Array.from(e.target.files || []);
        if (files.length > 0) {
            await uploadFiles(files);
        }
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDrop = async (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const files = Array.from(e.dataTransfer.files);
        if (files.length > 0) {
            await uploadFiles(files);
        }
    };

    const uploadFiles = async (files: File[]) => {
        const validFiles = files.filter(file => {
            const isImage = file.type.startsWith('image/');
            const isUnderLimit = file.size <= 50 * 1024 * 1024; // 50MB

            if (!isImage) addToast(`Skipped ${file.name}: Not an image`, 'error');
            if (!isUnderLimit) addToast(`Skipped ${file.name}: File too large (max 50MB)`, 'error');

            return isImage && isUnderLimit;
        });

        if (validFiles.length === 0) {
            return;
        }

        if (previews.length + validFiles.length > maxFiles) {
            addToast(`Maximum ${maxFiles} images allowed`, 'error');
            return;
        }

        setIsUploading(true);
        const formData = new FormData();
        validFiles.forEach(file => {
            formData.append('images', file);
        });

        try {
            const response = await api.post('/upload', formData, {
                headers: {
                    'Content-Type': 'multipart/form-data',
                },
            });

            const newUrls = response.data.imageUrls.map((url: string) => `http://localhost:5000${url}`);
            const updatedPreviews = [...previews, ...newUrls];

            setPreviews(updatedPreviews);
            onImagesUploaded(updatedPreviews);
            addToast('Images uploaded successfully', 'success');
        } catch (error: any) {
            addToast(error.message || 'Upload failed', 'error');
        } finally {
            setIsUploading(false);
            if (fileInputRef.current) {
                fileInputRef.current.value = '';
            }
        }
    };

    const handleRemove = (indexToRemove: number) => {
        const updatedPreviews = previews.filter((_, index) => index !== indexToRemove);
        setPreviews(updatedPreviews);
        onImagesUploaded(updatedPreviews);
    };

    return (
        <div className="w-full">
            <label className="block text-sm font-medium text-gray-700 mb-2">
                {label} <span className="text-gray-400 text-xs">({previews.length}/{maxFiles})</span>
            </label>

            <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileSelect}
                accept="image/*"
                multiple
                className="hidden"
            />

            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                {previews.map((url, index) => (
                    <div key={index} className="relative rounded-xl overflow-hidden group aspect-square bg-gray-100 border border-gray-200">
                        <img src={url} alt={`Preview ${index + 1}`} className="w-full h-full object-cover" />
                        <button
                            type="button"
                            onClick={() => handleRemove(index)}
                            className="absolute top-2 right-2 p-1.5 bg-red-500/90 rounded-full hover:bg-red-500 transition-colors text-white opacity-0 group-hover:opacity-100"
                            title="Remove Image"
                        >
                            <X className="w-4 h-4" />
                        </button>
                    </div>
                ))}

                {previews.length < maxFiles && (
                    <div
                        onClick={() => fileInputRef.current?.click()}
                        onDragOver={handleDragOver}
                        onDragLeave={handleDragLeave}
                        onDrop={handleDrop}
                        className={`
                            relative aspect-square rounded-xl border-2 border-dashed transition-all cursor-pointer flex flex-col items-center justify-center gap-2
                            ${isDragging ? 'border-primary bg-primary/5' : 'border-gray-300 hover:border-primary hover:bg-gray-50'}
                            ${isUploading ? 'opacity-50 cursor-not-allowed' : ''}
                        `}
                    >
                        {isUploading ? (
                            <Loader2 className="w-8 h-8 text-primary animate-spin" />
                        ) : (
                            <>
                                <div className={`p-3 rounded-full ${isDragging ? 'bg-primary/10' : 'bg-gray-100'}`}>
                                    <Upload className={`w-5 h-5 ${isDragging ? 'text-primary' : 'text-gray-400'}`} />
                                </div>
                                <span className="text-xs font-medium text-gray-500">Upload</span>
                            </>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { useStore } from '../../store/useStore';
import { useToast } from '../../context/ToastContext';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Plus } from 'lucide-react';
import { MultiImageUpload } from '../common/MultiImageUpload';
import { useCategories } from '../../hooks/useCategories';

import { useAuthStore } from '../../store/useAuthStore';

export function AddProductForm() {
    const addProduct = useStore((state) => state.addProduct);
    const user = useAuthStore((state) => state.user);
    const { categories } = useCategories();
    const { addToast } = useToast();
    const [isLoading, setIsLoading] = useState(false);

    const [formData, setFormData] = useState({
        name: '',
        price: '',
        originalPrice: '',
        stock: '',
        category: '',
        brand: '',
        description: '',
        images: [] as string[],
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user) {
            addToast('You must be logged in to add a product', 'error');
            return;
        }

        if (formData.images.length === 0) {
            addToast('Please upload at least one image', 'error');
            return;
        }

        setIsLoading(true);
        try {
            await addProduct({
                name: formData.name,
                price: Number(formData.price),
                originalPrice: formData.originalPrice ? Number(formData.originalPrice) : undefined,
                stock: formData.stock ? Number(formData.stock) : 0,
                category: formData.category,
                description: formData.description,
                image: formData.images[0], // Backend handles this, but sending just in case
                images: formData.images,
                brand: formData.brand,
                sellerId: user.id,
            });

            setFormData({
                name: '',
                price: '',
                originalPrice: '',
                stock: '',
                category: '',
                brand: '',
                description: '',
                images: []
            });
            addToast('Product added successfully!', 'success');
        } catch (error) {
            addToast('Failed to add product. Please try again.', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-5">
            <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                <Input
                    label="Product Name"
                    placeholder="e.g. Alphonso Mangoes"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    className="rounded-xl border-gray-200 focus:border-primary focus:ring-primary/20"
                    required
                />
                <div className="grid grid-cols-2 gap-4">
                    <Input
                        label="Price (₹)"
                        type="number"
                        placeholder="0.00"
                        value={formData.price}
                        onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                        className="rounded-xl border-gray-200 focus:border-primary focus:ring-primary/20"
                        required
                    />
                    <Input
                        label="Original Price (₹)"
                        type="number"
                        placeholder="Optional"
                        value={formData.originalPrice}
                        onChange={(e) => setFormData({ ...formData, originalPrice: e.target.value })}
                        className="rounded-xl border-gray-200 focus:border-primary focus:ring-primary/20"
                    />
                </div>
            </div>

            <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                <div className="space-y-1">
                    <label className="text-sm font-medium text-gray-700">Category</label>
                    <select
                        value={formData.category}
                        onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                        className="w-full rounded-xl border border-gray-200 p-3 text-sm focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20 bg-white"
                        required
                    >
                        <option value="">Select a Category</option>
                        {categories.map((cat) => (
                            <option key={cat.id} value={cat.name}>
                                {cat.name}
                            </option>
                        ))}
                    </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <Input
                        label="Stock Quantity"
                        type="number"
                        placeholder="0"
                        value={formData.stock}
                        onChange={(e) => setFormData({ ...formData, stock: e.target.value })}
                        className="rounded-xl border-gray-200 focus:border-primary focus:ring-primary/20"
                        required
                    />
                    <Input
                        label="Brand (Optional)"
                        placeholder="e.g. Local Farm"
                        value={formData.brand}
                        onChange={(e) => setFormData({ ...formData, brand: e.target.value })}
                        className="rounded-xl border-gray-200 focus:border-primary focus:ring-primary/20"
                    />
                </div>
            </div>

            <div>
                <MultiImageUpload
                    onImagesUploaded={(urls) => setFormData(prev => ({ ...prev, images: urls }))}
                    currentImages={formData.images}
                    label="Product Images"
                    maxFiles={5}
                />
            </div>

            <div className="space-y-1">
                <label className="text-sm font-medium text-gray-700">Description</label>
                <textarea
                    rows={3}
                    className="w-full rounded-xl border border-gray-200 p-3 text-sm focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                    placeholder="Describe your product..."
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    required
                />
            </div>

            <Button
                type="submit"
                disabled={isLoading}
                className="w-full rounded-xl py-6 text-base font-semibold shadow-lg shadow-primary/20 transition-all hover:shadow-primary/40 active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed"
            >
                {isLoading ? (
                    <span className="flex items-center gap-2">Processing...</span>
                ) : (
                    <>
                        <Plus className="mr-2 h-5 w-5" />
                        Add Product to Inventory
                    </>
                )}
            </Button>
        </form>
    );
}

import { createContext, useContext, useState, useCallback, type ReactNode } from 'react';
import { X, CheckCircle, AlertCircle, Info } from 'lucide-react';

type ToastType = 'success' | 'error' | 'info';

interface Toast {
    id: string;
    message: string;
    type: ToastType;
}

interface ToastContextType {
    addToast: (message: string, type?: ToastType) => void;
    removeToast: (id: string) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export function ToastProvider({ children }: { children: ReactNode }) {
    const [toasts, setToasts] = useState<Toast[]>([]);

    const addToast = useCallback((message: string, type: ToastType = 'info') => {
        const id = Math.random().toString(36).substr(2, 9);
        setToasts((prev) => [...prev, { id, message, type }]);

        // Auto-remove after 3 seconds
        setTimeout(() => {
            setToasts((prev) => prev.filter((t) => t.id !== id));
        }, 3000);
    }, []);

    const removeToast = useCallback((id: string) => {
        setToasts((prev) => prev.filter((t) => t.id !== id));
    }, []);

    return (
        <ToastContext.Provider value={{ addToast, removeToast }}>
            {children}
            <div className="fixed bottom-4 right-4 z-[100] flex flex-col gap-2 pointer-events-none">
                {toasts.map((toast) => (
                    <div
                        key={toast.id}
                        className={`
                            pointer-events-auto flex items-center gap-3 px-4 py-3 rounded-xl shadow-lg border backdrop-blur-md transition-all animate-slide-in
                            ${toast.type === 'success' ? 'bg-white/90 border-green-100 text-green-800' : ''}
                            ${toast.type === 'error' ? 'bg-white/90 border-red-100 text-red-800' : ''}
                            ${toast.type === 'info' ? 'bg-white/90 border-blue-100 text-blue-800' : ''}
                        `}
                    >
                        {toast.type === 'success' && <CheckCircle className="h-5 w-5 text-green-500" />}
                        {toast.type === 'error' && <AlertCircle className="h-5 w-5 text-red-500" />}
                        {toast.type === 'info' && <Info className="h-5 w-5 text-blue-500" />}

                        <p className="text-sm font-medium pr-4">{toast.message}</p>

                        <button
                            onClick={() => removeToast(toast.id)}
                            className="p-1 hover:bg-black/5 rounded-full transition-colors"
                        >
                            <X className="h-4 w-4 opacity-50" />
                        </button>
                    </div>
                ))}
            </div>
        </ToastContext.Provider>
    );
}

export function useToast() {
    const context = useContext(ToastContext);
    if (context === undefined) {
        throw new Error('useToast must be used within a ToastProvider');
    }
    return context;
}

import { useState, useEffect } from 'react';
import api from '../lib/api';

export interface Category {
    id: string;
    name: string;
    image: string;
    description?: string;
}

export function useCategories() {
    const [categories, setCategories] = useState<Category[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchCategories = async () => {
            try {
                const response = await api.get('/categories');
                setCategories(response.data);
                setError(null);
            } catch (err: any) {
                console.error('Failed to fetch categories:', err);
                setError(err.message || 'Failed to load categories');
            } finally {
                setIsLoading(false);
            }
        };

        fetchCategories();
    }, []);

    return { categories, isLoading, error };
}

