                <div className="h-16 flex items-center px-6 border-b border-gray-200">
                    <ShieldCheck className="h-8 w-8 text-primary" />
                    <span className="ml-2 text-xl font-bold text-gray-900">Admin Panel</span>
                </div>

                <div className="p-4">
                    <nav className="space-y-1">
                        {navigation.map((item) => {
                            const Icon = item.icon;
                            return (
                                <button
                                    key={item.id}
                                    onClick={() => {
                                        setActiveTab(item.id as any);
                                        setIsSidebarOpen(false);
                                    }}
                                    className={`
                                        w-full flex items-center px-4 py-3 text-sm font-medium rounded-lg transition-colors
                                        ${activeTab === item.id
                                            ? 'bg-primary/10 text-primary'
                                            : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'}
                                    `}
                                >
                                    <Icon className={`mr-3 h-5 w-5 ${activeTab === item.id ? 'text-primary' : 'text-gray-400'}`} />
                                    {item.name}
                                </button>
                            );
                        })}

                        <div className="pt-4 mt-4 border-t border-gray-100 space-y-2">
                            <a href="/seller" className="w-full flex items-center px-4 py-3 text-sm font-medium text-gray-600 hover:bg-gray-50 hover:text-primary transition-colors rounded-lg">
                                <Store className="mr-3 h-5 w-5 text-gray-400" />
                                Seller View
                            </a>
                            <a href="/delivery" className="w-full flex items-center px-4 py-3 text-sm font-medium text-gray-600 hover:bg-gray-50 hover:text-primary transition-colors rounded-lg">
                                <Truck className="mr-3 h-5 w-5 text-gray-400" />
                                Delivery View
                            </a>
                            <a href="/" className="w-full flex items-center px-4 py-3 text-sm font-medium text-gray-600 hover:bg-gray-50 hover:text-primary transition-colors rounded-lg">
                                <ShoppingBag className="mr-3 h-5 w-5 text-gray-400" />
                                Switch to Buying
                            </a>
                        </div>
                    </nav>
                </div>

                <div className="p-4 absolute bottom-0 w-full border-t border-gray-200 bg-white">
                    <div className="flex items-center gap-3 px-4 py-3 mb-2">
                        <div className="h-10 w-10 rounded-full bg-gray-100 flex items-center justify-center">
                            <span className="font-semibold text-gray-600">{user.name.charAt(0)}</span>
                        </div>
                        <div className="overflow-hidden">
                            <p className="text-sm font-medium text-gray-900 truncate">{user.name}</p>
                            <p className="text-xs text-gray-500 truncate">{user.email}</p>
                        </div>
                    </div>
                    <button
                        onClick={logout}
                        className="w-full flex items-center px-4 py-2 text-sm font-medium text-red-600 rounded-lg hover:bg-red-50 transition-colors"
                    >
                        <LogOut className="mr-3 h-5 w-5" />
                        Sign Out
                    </button>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                {/* Mobile Header */}
                <div className="lg:hidden flex items-center justify-between bg-white border-b border-gray-200 px-4 py-3">
                    <button
                        onClick={() => setIsSidebarOpen(true)}
                        className="p-2 -ml-2 text-gray-600 hover:bg-gray-100 rounded-md"
                    >
                        <Menu className="h-6 w-6" />
                    </button>
                    <span className="font-semibold text-gray-900">Admin Panel</span>
                    <div className="w-8" /> {/* Spacer for centering */}
                </div>

                <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
                    <div className="max-w-7xl mx-auto">
                        <div className="mb-6">
                            <h1 className="text-2xl font-bold text-gray-900">
                                {navigation.find(n => n.id === activeTab)?.name}
                            </h1>
                        </div>
                        {renderContent()}
                    </div>
                </main>
            </div>
        </div>
    );
};

import { useState, useEffect } from 'react';
import { useStore } from '../store/useStore';
import { MainLayout } from '../components/layout/MainLayout';
import { Button } from '../components/ui/Button';
import { MapPin, CreditCard, ShoppingBag, ArrowRight } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { useToast } from '../context/ToastContext';
import { AddressFormModal } from '../components/address/AddressFormModal';
import api from '../lib/api';

const steps = [
    { id: 1, label: 'Address', icon: MapPin },
    { id: 2, label: 'Payment', icon: CreditCard },
    { id: 3, label: 'Review', icon: ShoppingBag },
];

export function CheckoutPage() {
    const { cart, user, placeOrder, clearCart } = useStore();
    const navigate = useNavigate();
    const { addToast } = useToast();
    const [currentStep, setCurrentStep] = useState(1);
    const [addresses, setAddresses] = useState<any[]>([]);
    const [selectedAddressId, setSelectedAddressId] = useState<string>('');
    const [selectedPayment, setSelectedPayment] = useState('cod');
    const [isAddressModalOpen, setIsAddressModalOpen] = useState(false);
    const [isLoadingAddresses, setIsLoadingAddresses] = useState(false);
    const [isPlacingOrder, setIsPlacingOrder] = useState(false);

    const fetchAddresses = async () => {
        setIsLoadingAddresses(true);
        try {
            const response = await api.get('/user/address');
            const data = response.data;
            setAddresses(data);
            // Select default address if available, else first one
            const defaultAddr = data.find((a: any) => a.isDefault);
            if (defaultAddr && !selectedAddressId) setSelectedAddressId(defaultAddr.id);
            else if (data.length > 0 && !selectedAddressId) setSelectedAddressId(data[0].id);
        } catch (error) {
            console.error('Failed to fetch addresses', error);
        } finally {
            setIsLoadingAddresses(false);
        }
    };

    useEffect(() => {
        if (currentStep === 1) {
            fetchAddresses();
        }
    }, [currentStep]);

    const subtotal = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);
    const total = subtotal + 40 + 5; // Delivery + Platform fee

    const handlePlaceOrder = async () => {
        if (!user) return;
        if (!selectedAddressId) {
            addToast('Please select a delivery address', 'error');
            return;
        }

        setIsPlacingOrder(true);

        try {
            // Send items directly to backend as per new plan
            const response = await api.post('/orders', {
                items: cart.map(item => ({
                    productId: item.id,
                    quantity: item.quantity
                })),
                deliveryAddress: addresses.find(a => a.id === selectedAddressId)?.id
                    ? `${addresses.find(a => a.id === selectedAddressId)?.street}, ${addresses.find(a => a.id === selectedAddressId)?.village}, ${addresses.find(a => a.id === selectedAddressId)?.city} - ${addresses.find(a => a.id === selectedAddressId)?.pincode}`
                    : 'Unknown Address'
            });

            if (response.status === 201) {
                // Update local store (legacy) - optional if we move to full backend sync
                const newOrder = {
                    id: response.data.order.id,
                    items: [...cart],
                    total,
                    status: 'pending' as const,
                    customerName: user.name,
                    deliveryAddress: response.data.order.deliveryAddress,
                    createdAt: new Date().toISOString(),
                };
                placeOrder(newOrder);

                clearCart();
                addToast('Order placed successfully! 🎉', 'success');
                navigate('/orders');
            }
        } catch (error) {
            console.error(error);
            addToast('Failed to place order', 'error');
        } finally {
            setIsPlacingOrder(false);
        }
    };

    if (cart.length === 0) {
        return (
            <MainLayout>
                <div className="flex flex-col items-center justify-center min-h-[60vh]">
                    <ShoppingBag className="h-20 w-20 text-gray-200 mb-6" />
                    <h2 className="text-2xl font-bold text-gray-900 mb-2">Your cart is empty</h2>
                    <Link to="/">
                        <Button>Continue Shopping</Button>
                    </Link>
                </div>
            </MainLayout>
        );
    }

    return (
        <MainLayout>
            <div className="max-w-4xl mx-auto">
                {/* Steps */}
                <div className="mb-12">
                    <div className="flex justify-between items-center relative">
                        <div className="absolute left-0 top-1/2 w-full h-1 bg-gray-100 -z-10 rounded-full" />
                        <div
                            className="absolute left-0 top-1/2 h-1 bg-primary -z-10 rounded-full transition-all duration-500"
                            style={{ width: `${((currentStep - 1) / 2) * 100}%` }}
                        />
                        {steps.map((step) => (
                            <div key={step.id} className="flex flex-col items-center gap-2 bg-gray-50 p-2 rounded-xl">
                                <div className={`h-10 w-10 rounded-full flex items-center justify-center border-2 transition-all ${currentStep >= step.id
                                    ? 'bg-primary border-primary text-white scale-110 shadow-lg shadow-primary/25'
                                    : 'bg-white border-gray-200 text-gray-400'
                                    }`}>
                                    <step.icon className="h-5 w-5" />
                                </div>
                                <span className={`text-sm font-semibold ${currentStep >= step.id ? 'text-primary' : 'text-gray-400'}`}>{step.label}</span>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* Main Content */}
                    <div className="lg:col-span-2 space-y-6">

                        {/* Step 1: Address */}
                        {currentStep === 1 && (
                            <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm animate-fade-in">
                                <h2 className="text-xl font-bold text-gray-900 mb-6">Select Delivery Address</h2>
                                <div className="space-y-4">
                                    {isLoadingAddresses ? (
                                        <div className="text-center py-4">Loading addresses...</div>
                                    ) : addresses.length === 0 ? (
                                        <div className="text-center py-6 text-gray-500">
                                            No addresses found. Please add a new address.
                                        </div>
                                    ) : (
                                        addresses.map((addr) => (
                                            <div
                                                key={addr.id}
                                                onClick={() => setSelectedAddressId(addr.id)}
                                                className={`p-4 rounded-xl border-2 cursor-pointer transition-all flex items-start gap-4 ${selectedAddressId === addr.id
                                                    ? 'border-primary bg-primary/5'
                                                    : 'border-gray-100 hover:border-gray-200'
                                                    }`}
                                            >
                                                <div className={`h-5 w-5 rounded-full border-2 mt-1 flex items-center justify-center ${selectedAddressId === addr.id ? 'border-primary' : 'border-gray-300'
                                                    }`}>
                                                    {selectedAddressId === addr.id && <div className="h-2.5 w-2.5 rounded-full bg-primary" />}
                                                </div>
                                                <div>
                                                    <div className="flex items-center gap-2 mb-1">
                                                        <span className="font-bold text-gray-900 capitalize">{addr.type}</span>
                                                        {addr.isDefault && <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded">Default</span>}
                                                    </div>
                                                    <p className="text-gray-600 text-sm">
                                                        {addr.street}
                                                    </p>
                                                    <p className="text-gray-600 text-sm">
                                                        {addr.village}, {addr.city} - {addr.pincode}
                                                    </p>
                                                    <div className="flex gap-4 mt-2 text-sm text-gray-500">
                                                        <p>Ph: {addr.phone}</p>
                                                        {addr.alternatePhone && <p>Alt: {addr.alternatePhone}</p>}
                                                    </div>
                                                </div>
                                            </div>
                                        ))
                                    )}
                                    <Button variant="outline" className="w-full border-dashed" onClick={() => setIsAddressModalOpen(true)}>
                                        + Add New Address
                                    </Button>
                                </div>
                            </div>
                        )}

                        {/* Step 2: Payment */}
                        {currentStep === 2 && (
                            <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm animate-fade-in">
                                <h2 className="text-xl font-bold text-gray-900 mb-6">Select Payment Method</h2>
                                <div className="space-y-4">
                                    {[
                                        { id: 'upi', label: 'UPI (GPay / PhonePe)', icon: '📱' },
                                        { id: 'card', label: 'Credit / Debit Card', icon: '💳' },
                                        { id: 'cod', label: 'Cash on Delivery', icon: '💵' }
                                    ].map((method) => (
                                        <div
                                            key={method.id}
                                            onClick={() => setSelectedPayment(method.id)}
                                            className={`p-4 rounded-xl border-2 cursor-pointer transition-all flex items-center gap-4 ${selectedPayment === method.id
                                                ? 'border-primary bg-primary/5'
                                                : 'border-gray-100 hover:border-gray-200'
                                                }`}
                                        >
                                            <div className={`h-5 w-5 rounded-full border-2 flex items-center justify-center ${selectedPayment === method.id ? 'border-primary' : 'border-gray-300'
                                                }`}>
                                                {selectedPayment === method.id && <div className="h-2.5 w-2.5 rounded-full bg-primary" />}
                                            </div>
                                            <span className="text-2xl">{method.icon}</span>
                                            <span className="font-bold text-gray-900">{method.label}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Step 3: Review */}
                        {currentStep === 3 && (
                            <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm animate-fade-in">
                                <h2 className="text-xl font-bold text-gray-900 mb-6">Review Order</h2>
                                <div className="space-y-4 mb-6">
                                    {cart.map((item) => (
                                        <div key={item.id} className="flex gap-4">
                                            <div className="h-16 w-16 bg-gray-100 rounded-lg overflow-hidden">
                                                <img src={item.image} alt={item.name} className="h-full w-full object-cover" />
                                            </div>
                                            <div>
                                                <p className="font-semibold text-gray-900">{item.name}</p>
                                                <p className="text-sm text-gray-500">Qty: {item.quantity}</p>
                                                <p className="text-sm font-bold text-gray-900">₹{item.price * item.quantity}</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <div className="bg-gray-50 p-4 rounded-xl text-sm text-gray-600 space-y-2">
                                    <p><span className="font-semibold">Deliver to:</span> {addresses.find(a => a.id === selectedAddressId)?.type || 'Selected Address'}</p>
                                    <p><span className="font-semibold">Address:</span> {addresses.find(a => a.id === selectedAddressId)?.village}, {addresses.find(a => a.id === selectedAddressId)?.city}</p>
                                    <p><span className="font-semibold">Payment:</span> {selectedPayment.toUpperCase()}</p>
                                </div>
                            </div>
                        )}

                        <div className="flex gap-4 pt-4">
                            {currentStep > 1 && (
                                <Button variant="outline" onClick={() => setCurrentStep(c => c - 1)} className="flex-1">
                                    Back
                                </Button>
                            )}
                            <Button
                                className="flex-1 shadow-lg shadow-primary/25"
                                onClick={() => currentStep === 3 ? handlePlaceOrder() : setCurrentStep(c => c + 1)}
                                disabled={isPlacingOrder}
                            >
                                {isPlacingOrder ? 'Placing Order...' : currentStep === 3 ? 'Place Order' : 'Continue'}
                                {currentStep !== 3 && <ArrowRight className="ml-2 h-5 w-5" />}
                            </Button>
                        </div>
                    </div>

                    {/* Order Summary */}
                    <div className="lg:col-span-1">
                        <div className="bg-white rounded-3xl border border-gray-100 shadow-sm p-6 sticky top-24">
                            <h3 className="text-xl font-bold text-gray-900 mb-6">Order Summary</h3>
                            <div className="space-y-4 mb-6">
                                <div className="flex justify-between text-gray-600">
                                    <span>Subtotal</span>
                                    <span>₹{subtotal}</span>
                                </div>
                                <div className="flex justify-between text-gray-600">
                                    <span>Delivery Fee</span>
                                    <span className="text-green-600">₹40</span>
                                </div>
                                <div className="flex justify-between text-gray-600">
                                    <span>Platform Fee</span>
                                    <span>₹5</span>
                                </div>
                                <div className="h-px bg-gray-100" />
                                <div className="flex justify-between text-lg font-bold text-gray-900">
                                    <span>Total</span>
                                    <span>₹{total}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <AddressFormModal
                isOpen={isAddressModalOpen}
                onClose={() => setIsAddressModalOpen(false)}
                onSuccess={() => {
                    fetchAddresses();
                    setIsAddressModalOpen(false);
                }}
            />
        </MainLayout>
    );
}

import { useEffect } from 'react';
import { useStore } from '../store/useStore';
import { useSocket } from '../hooks/useSocket';
import { useToast } from '../context/ToastContext';
import { MainLayout } from '../components/layout/MainLayout';
import { Badge } from '../components/ui/Badge';
import { Button } from '../components/ui/Button';
import { MapPin, Package, Truck } from 'lucide-react';

import { useAuthStore } from '../store/useAuthStore';

export function DeliveryDashboard() {
    const { orders, assignDeliveryMan, updateOrderStatus, setOrders } = useStore();
    const { user } = useAuthStore();
    const socket = useSocket();
    const { addToast } = useToast();
    const token = localStorage.getItem('token');

    const fetchOrders = async () => {
        try {
            // Fetch relevant orders for delivery (all ready for pickup + my active ones)
            // For now fetching all orders might be simplest if the backend filters or if we filter client side
            // Ideally we need an endpoint for delivery dashboard
            const response = await fetch('http://localhost:5000/api/orders/my-orders', {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (response.ok) {
                const data = await response.json();
                setOrders(data);
            }
        } catch (error) {
            console.error('Failed to fetch orders', error);
        }
    };

    useEffect(() => {
        fetchOrders();

        if (socket) {
            socket.on('new_order', () => {
                fetchOrders();
            });

            socket.on('order_status_updated', (data: any) => {
                if (data.status === 'ready_for_pickup') {
                    addToast('New order ready for pickup!', 'success');
                }
                fetchOrders();
            });
        }

        return () => {
            if (socket) {
                socket.off('new_order');
                socket.off('order_status_updated');
            }
        };
    }, [socket, addToast]);

    // Available orders: status is 'ready_for_pickup' and no delivery man assigned
    const availableOrders = orders.filter(o => o.status === 'ready_for_pickup' && !o.deliveryManId);

    // My active deliveries: assigned to current user and not delivered
    const myDeliveries = orders.filter(o => o.deliveryManId === user?.id && o.status !== 'delivered');

    const handleAcceptOrder = (orderId: string) => {
        if (user) {
            assignDeliveryMan(orderId, user.id);
        }
    };

    return (
        <MainLayout>
            <div className="container mx-auto px-4 py-8">
                <div className="mb-10 flex items-end justify-between">
                    <div>
                        <h1 className="text-4xl font-extrabold text-gray-900 tracking-tight">Delivery Dashboard</h1>
                        <p className="mt-2 text-lg text-gray-600">You are the city's lifeline, <span className="font-semibold text-primary">{user?.name}</span>.</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 gap-8 lg:grid-cols-2">
                    {/* Available Orders */}
                    <div className="space-y-6">
                        <div className="flex items-center gap-3 mb-2">
                            <div className="p-2 bg-indigo-100 rounded-lg text-indigo-600">
                                <Package className="h-6 w-6" />
                            </div>
                            <h2 className="text-xl font-bold text-gray-900">Available for Pickup</h2>
                        </div>

                        {availableOrders.length === 0 ? (
                            <div className="rounded-3xl border border-dashed border-gray-300 p-12 text-center">
                                <p className="text-gray-500 text-lg">No orders ready for pickup right now.</p>
                                <p className="text-sm text-gray-400 mt-1">Check back in a moment!</p>
                            </div>
                        ) : (
                            availableOrders.map(order => (
                                <div key={order.id} className="group relative overflow-hidden rounded-3xl border border-gray-100 bg-white p-6 shadow-xl shadow-gray-200/50 transition-all hover:-translate-y-1 hover:shadow-2xl hover:shadow-indigo-500/10">
                                    <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:scale-110 transition-transform">
                                        <Package className="h-24 w-24 text-primary" />
                                    </div>

                                    <div className="relative z-10">
                                        <div className="mb-4 flex justify-between items-start">
                                            <div>
                                                <span className="inline-block px-3 py-1 rounded-full bg-gray-100 text-xs font-bold text-gray-600 mb-2">Order #{order.id}</span>
                                                <div className="flex items-baseline gap-1">
                                                    <span className="text-2xl font-bold text-gray-900">₹{order.total + 50}</span>
                                                    <span className="text-sm font-medium text-green-600 bg-green-50 px-2 py-0.5 rounded-full ml-2">Earn ₹50</span>
                                                </div>
                                            </div>
                                        </div>

                                        <div className="mb-6 space-y-3">
                                            <div className="flex items-start gap-3 p-3 rounded-xl bg-gray-50">
                                                <MapPin className="mt-1 h-5 w-5 text-red-500 shrink-0" />
                                                <div>
                                                    <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">drop location</p>
                                                    <p className="font-medium text-gray-900">{order.deliveryAddress}</p>
                                                </div>
                                            </div>
                                            <p className="pl-4 text-sm text-gray-500 flex items-center gap-2">
                                                <div className="w-1.5 h-1.5 rounded-full bg-gray-300"></div>
                                                Contains {order.items.length} items
                                            </p>
                                        </div>

                                        <Button
                                            className="w-full rounded-xl py-6 text-base shadow-lg shadow-indigo-500/20"
                                            onClick={() => handleAcceptOrder(order.id)}
                                        >
                                            Accept Delivery
                                        </Button>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>

                    {/* My Active Deliveries */}
                    <div className="space-y-6">
                        <div className="flex items-center gap-3 mb-2">
                            <div className="p-2 bg-green-100 rounded-lg text-green-600">
                                <Truck className="h-6 w-6" />
                            </div>
                            <h2 className="text-xl font-bold text-gray-900">My Active Deliveries</h2>
                        </div>

                        {myDeliveries.length === 0 ? (
                            <div className="rounded-3xl border border-dashed border-gray-300 p-12 text-center bg-gray-50/50">
                                <p className="text-gray-500 text-lg">No active deliveries.</p>
                                <p className="text-sm text-gray-400 mt-1">Accept an order to get started!</p>
                            </div>
                        ) : (
                            myDeliveries.map(order => (
                                <div key={order.id} className="rounded-3xl border border-blue-100 bg-gradient-to-br from-blue-50 to-white p-6 shadow-xl shadow-blue-500/5">
                                    <div className="mb-6 flex justify-between items-center">
                                        <span className="font-bold text-gray-900">Order #{order.id}</span>
                                        <Badge className="bg-blue-100 text-blue-700 hover:bg-blue-200 uppercase tracking-wide text-xs px-3 py-1">
                                            {order.status.replace('_', ' ')}
                                        </Badge>
                                    </div>

                                    <div className="mb-6 space-y-4">
                                        <div className="flex items-start gap-4">
                                            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-white shadow-sm text-lg">📍</div>
                                            <div>
                                                <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">Deliver To</p>
                                                <p className="font-semibold text-gray-900 text-lg">{order.deliveryAddress}</p>
                                                <p className="text-sm text-gray-500">{order.customerName}</p>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex gap-2">
                                        {/* Logic for status updates */}
                                        {order.status === 'ready_for_pickup' || order.status === 'preparing' ? (
                                            <Button
                                                className="w-full rounded-xl py-6 text-base font-semibold"
                                                onClick={() => updateOrderStatus(order.id, 'picked_up')}
                                            >
                                                Confirm Pickup
                                            </Button>
                                        ) : order.status === 'picked_up' ? (
                                            <Button
                                                className="w-full bg-green-600 hover:bg-green-700 rounded-xl py-6 text-base font-semibold shadow-lg shadow-green-500/20"
                                                onClick={() => updateOrderStatus(order.id, 'delivered')}
                                            >
                                                Mark Delivered
                                            </Button>
                                        ) : null}
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>
        </MainLayout>
    );
}

import { useNavigate } from 'react-router-dom';
import { useStore } from '../store/useStore';
import { useAuthStore } from '../store/useAuthStore';
import { ProductCard } from '../components/common/ProductCard';
import { MainLayout } from '../components/layout/MainLayout';
import { BannerSlider } from '../components/common/BannerSlider';
import { CategoryStrip } from '../components/common/CategoryStrip';
import { TimeBasedSection } from '../components/common/TimeBasedSection';
import { useEffect } from 'react';

export function HomePage() {
    const { products, searchQuery, selectedCategory } = useStore();
    const { user } = useAuthStore();
    const navigate = useNavigate();

    // Redirect functionality for special roles
    useEffect(() => {
        if (user) {
            if (user.role === 'seller') navigate('/seller');
            else if (user.role === 'delivery_man') navigate('/delivery');
            else if (user.role === 'ADMIN') navigate('/admin');
        }
    }, [user, navigate]);

    // Check if there is an active search query (ignoring whitespace)
    const isSearching = searchQuery.trim().length > 0;

    const filteredProducts = products.filter(product => {
        const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            product.category.toLowerCase().includes(searchQuery.toLowerCase());

        const matchesCategory = selectedCategory ? product.category === selectedCategory : true;

        return matchesSearch && matchesCategory;
    });

    const handleProductClick = (product: any) => {
        navigate(`/product/${product.id}`);
    };

    return (
        <MainLayout>
            {!isSearching && (
                <div className="container mx-auto px-4 py-4 space-y-6">
                    <CategoryStrip />
                    <BannerSlider />
                    <TimeBasedSection />
                </div>
            )}

            <div className="container mx-auto px-4">
                <div className="mb-6 flex items-center justify-between mt-8">
                    <h2 className="text-xl md:text-2xl font-bold text-gray-900">
                        {isSearching
                            ? `Search Results for "${searchQuery}"`
                            : selectedCategory
                                ? selectedCategory
                                : 'Trending Now'}
                    </h2>
                    {(isSearching || selectedCategory) && (
                        <button
                            onClick={() => {
                                useStore.getState().setSearchQuery('');
                                useStore.getState().setSelectedCategory(null);
                            }}
                            className="text-sm font-medium text-primary hover:text-primary-dark"
                        >
                            Clear Filters
                        </button>
                    )}
                </div>

                {filteredProducts.length === 0 ? (
                    <div className="text-center py-20">
                        <p className="text-xl text-gray-500">No products found matching "{searchQuery}"</p>
                        <p className="text-gray-400 mt-2">Try checking your spelling or using different keywords.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-2 gap-3 sm:gap-6 md:grid-cols-3 lg:grid-cols-4 pb-20 md:pb-8">
                        {filteredProducts.map((product) => (
                            <ProductCard
                                key={product.id}
                                product={product}
                                onClick={() => handleProductClick(product)}
                            />
                        ))}
                    </div>
                )}
            </div>
        </MainLayout>
    );
}

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuthStore } from '../store/useAuthStore';
import { useToast } from '../context/ToastContext';
import { Store, Mail, Lock, ArrowRight, Loader2 } from 'lucide-react';
import api from '../lib/api';

export const LoginPage = () => {
    const navigate = useNavigate();
    const { login } = useAuthStore();
    const { addToast } = useToast();

    const [formData, setFormData] = useState({
        email: '',
        password: ''
    });
    const [isLoading, setIsLoading] = useState(false);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setFormData(prev => ({
            ...prev,
            [e.target.name]: e.target.value
        }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            const response = await api.post('/auth/login', {
                identifier: formData.email, // We use the email field for both email/phone input
                password: formData.password
            });

            const data = response.data;

            login(data.user, data.token);
            addToast('Login successful!', 'success');

            // Redirect based on role
            if (data.user.role === 'seller') navigate('/seller');
            else if (data.user.role === 'delivery_man') navigate('/delivery');
            else if (data.user.role === 'ADMIN') navigate('/admin');
            else navigate('/');

        } catch (error: any) {
            addToast(error.response?.data?.message || 'Login failed', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex bg-white">
            {/* Left Side - Form */}
            <div className="w-full lg:w-1/2 flex flex-col justify-center px-4 sm:px-12 lg:px-24 py-12">
                <div className="sm:mx-auto sm:w-full sm:max-w-md">
                    <Link to="/" className="flex items-center gap-2 mb-8 group">
                        <div className="h-10 w-10 bg-primary/10 rounded-xl flex items-center justify-center group-hover:bg-primary/20 transition-colors">
                            <Store className="h-6 w-6 text-primary" />
                        </div>
                        <span className="text-xl font-bold text-gray-900">Vemgal Mart</span>
                    </Link>

                    <h2 className="text-3xl font-bold tracking-tight text-gray-900">
                        Welcome back
                    </h2>
                    <p className="mt-2 text-sm text-gray-600">
                        Don't have an account?{' '}
                        <Link to="/register" className="font-semibold text-primary hover:text-primary-dark transition-colors">
                            Sign up for free
                        </Link>
                    </p>
                </div>

                <div className="mt-10 sm:mx-auto sm:w-full sm:max-w-md">
                    <form className="space-y-6" onSubmit={handleSubmit}>
                        <div>
                            <label htmlFor="email" className="block text-sm font-medium text-gray-700">
                                Email or Phone
                            </label>
                            <div className="mt-1 relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <Mail className="h-5 w-5 text-gray-400 group-focus-within:hidden" />
                                </div>
                                <input
                                    id="email"
                                    name="email"
                                    type="text"
                                    required
                                    className="block w-full pl-10 pr-3 py-3 border border-gray-200 rounded-xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-gray-50 focus:bg-white"
                                    placeholder="you@example.com or +91..."
                                    value={formData.email}
                                    onChange={handleChange}
                                />
                            </div>
                        </div>

                        <div>
                            <div className="flex items-center justify-between">
                                <label htmlFor="password" className="block text-sm font-medium text-gray-700">
                                    Password
                                </label>
                                <div className="text-sm">
                                    <a href="#" className="font-medium text-primary hover:text-primary-dark">
                                        Forgot password?
                                    </a>
                                </div>
                            </div>
                            <div className="mt-1 relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <Lock className="h-5 w-5 text-gray-400" />
                                </div>
                                <input
                                    id="password"
                                    name="password"
                                    type="password"
                                    required
                                    className="block w-full pl-10 pr-3 py-3 border border-gray-200 rounded-xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-gray-50 focus:bg-white"
                                    placeholder="••••••••"
                                    value={formData.password}
                                    onChange={handleChange}
                                />
                            </div>
                        </div>

                        <button
                            type="submit"
                            disabled={isLoading}
                            className={`w-full flex justify-center items-center gap-2 py-3 px-4 border border-transparent rounded-xl shadow-sm text-sm font-semibold text-white bg-primary hover:bg-primary-dark focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-all ${isLoading ? 'opacity-70 cursor-not-allowed' : 'hover:shadow-lg hover:shadow-primary/30'}`}
                        >
                            {isLoading ? (
                                <>
                                    <Loader2 className="h-4 w-4 animate-spin" />
                                    Signing in...
                                </>
                            ) : (
                                <>
                                    Sign in <ArrowRight className="h-4 w-4" />
                                </>
                            )}
                        </button>
                    </form>

                    <div className="mt-8">
                        <div className="relative">
                            <div className="absolute inset-0 flex items-center">
                                <div className="w-full border-t border-gray-200" />
                            </div>
                            <div className="relative flex justify-center text-sm">
                                <span className="px-2 bg-white text-gray-500">
                                    Secure & encrypted
                                </span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Right Side - Image */}
            <div className="hidden lg:block lg:w-1/2 relative bg-gray-900">
                <div className="absolute inset-0 bg-gradient-to-br from-primary/40 to-black/60 z-10" />
                <img
                    className="absolute inset-0 h-full w-full object-cover opacity-80"
                    src="https://images.unsplash.com/photo-1578916171728-46686eac8d58?q=80&w=1974&auto=format&fit=crop"
                    alt="Shopping at Vemgal Mart"
                />
                <div className="relative z-20 h-full flex flex-col justify-end p-12 text-white">
                    <h3 className="text-4xl font-bold mb-4">Shop smarter, live better.</h3>
                    <p className="text-lg text-gray-200 max-w-md">
                        Experience the fastest delivery service in Vemgal. Fresh groceries, daily essentials, and more, right at your doorstep.
                    </p>
                </div>
            </div>
        </div>
    );
};

import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useStore } from '../store/useStore';
import { Button } from '../components/ui/Button';
import { ArrowLeft, ShoppingCart, Loader2, Minus, Plus } from 'lucide-react';
import api from '../lib/api';
import type { Product } from '../types';
import { MainLayout } from '../components/layout/MainLayout';

export function ProductDetailsPage() {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const { addToCart, products } = useStore();

    // Try to find in store first, otherwise null
    const [product, setProduct] = useState<Product | null>(
        products.find(p => p.id === id) || null
    );
    const [isLoading, setIsLoading] = useState(!product);
    const [activeImage, setActiveImage] = useState<string | null>(null);
    const [quantity, setQuantity] = useState(1);

    useEffect(() => {
        // If product not found in store or we want fresh data
        const fetchProduct = async () => {
            if (!id) return;
            try {
                const response = await api.get(`/products/${id}`);
                setProduct(response.data);
                if (!activeImage) setActiveImage(response.data.image);
            } catch (error) {
                console.error('Failed to fetch product', error);
                // Optionally redirect to 404
            } finally {
                setIsLoading(false);
            }
        };

        if (!product) {
            fetchProduct();
        } else {
            setActiveImage(product.image);
        }
    }, [id, product]);

    const handleAddToCart = () => {
        if (!product) return;
        for (let i = 0; i < quantity; i++) {
            addToCart(product);
        }
        setQuantity(1);
        // Optional: Show toast or navigate to cart
    };

    if (isLoading) {
        return (
            <MainLayout>
                <div className="flex h-[50vh] items-center justify-center">
                    <Loader2 className="h-8 w-8 animate-spin text-primary" />
                </div>
            </MainLayout>
        );
    }

    if (!product) {
        return (
            <MainLayout>
                <div className="flex h-[50vh] flex-col items-center justify-center gap-4">
                    <h2 className="text-xl font-bold text-gray-900">Product not found</h2>
                    <Button onClick={() => navigate('/')} variant="outline">
                        <ArrowLeft className="mr-2 h-4 w-4" /> Back to Home
                    </Button>
                </div>
            </MainLayout>
        );
    }

    return (
        <MainLayout>
            <div className="container mx-auto px-4 py-4 md:py-8 max-w-7xl">
                <Button
                    variant="ghost"
                    className="mb-4 md:mb-8"
                    onClick={() => navigate(-1)}
                >
                    <ArrowLeft className="mr-2 h-4 w-4" /> Back
                </Button>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12">
                    {/* Image Section */}
                    <div className="space-y-4">
                        <div className="aspect-square bg-gray-50 rounded-3xl overflow-hidden flex items-center justify-center p-8 border border-gray-100">
                            <img
                                src={activeImage || product.image}
                                alt={product.name}
                                className="max-w-full max-h-full object-contain mix-blend-multiply transition-transform duration-500 hover:scale-105"
                            />
                        </div>

                        {/* Thumbnails */}
                        {/* Thumbnails */}
                        {product.images && product.images.length > 0 ? (
                            <div className="flex gap-4 overflow-x-auto pb-2 custom-scrollbar">
                                {product.images.map((img, idx) => (
                                    <button
                                        key={idx}
                                        onClick={() => setActiveImage(img)}
                                        className={`relative w-20 h-20 rounded-xl overflow-hidden border-2 flex-shrink-0 transition-all ${activeImage === img ? 'border-primary ring-2 ring-primary/20' : 'border-gray-100 hover:border-gray-200'}`}
                                    >
                                        <img src={img} alt={`View ${idx + 1}`} className="w-full h-full object-cover" />
                                    </button>
                                ))}
                            </div>
                        ) : product.image && (
                            <div className="flex gap-4 overflow-x-auto pb-2 custom-scrollbar">
                                <button
                                    onClick={() => setActiveImage(product.image)}
                                    className={`relative w-20 h-20 rounded-xl overflow-hidden border-2 flex-shrink-0 transition-all ${activeImage === product.image ? 'border-primary ring-2 ring-primary/20' : 'border-gray-100 hover:border-gray-200'}`}
                                >
                                    <img src={product.image} alt="Main" className="w-full h-full object-cover" />
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Details Section */}
                    <div className="flex flex-col">
                        <div>
                            <p className="text-sm md:text-base font-medium text-primary mb-2">
                                {product.seller?.shopName || product.seller?.name || 'Vemgal Mart'}
                            </p>
                            <h1 className="text-2xl md:text-4xl font-bold text-gray-900 leading-tight mb-2">{product.name}</h1>
                            <p className="text-sm md:text-base text-gray-500 mb-6">{product.category}</p>

                            <div className="flex items-center gap-4 mb-8">
                                <div className="flex items-baseline gap-2">
                                    <span className="text-3xl md:text-4xl font-bold text-gray-900">₹{product.price}</span>
                                    {product.originalPrice && product.originalPrice > product.price && (
                                        <span className="text-xl text-gray-400 line-through">₹{product.originalPrice}</span>
                                    )}
                                </div>
                                {product.stock !== undefined && (
                                    <span className={`px-3 py-1 rounded-full text-sm font-bold border ${product.stock > 0
                                        ? 'bg-green-50 text-green-700 border-green-100'
                                        : 'bg-red-50 text-red-700 border-red-100'
                                        }`}>
                                        {product.stock > 0 ? `In Stock (${product.stock})` : 'Out of Stock'}
                                    </span>
                                )}
                            </div>

                            <div className="prose prose-lg text-gray-600 mb-8 max-w-none">
                                <p>{product.description}</p>
                            </div>
                        </div>

                        <div className="mt-auto pt-8 border-t border-gray-100">
                            <div className="flex flex-col sm:flex-row gap-4">
                                <div className="flex items-center border-2 border-gray-200 rounded-xl w-full sm:w-auto">
                                    <button
                                        onClick={() => setQuantity(Math.max(1, quantity - 1))}
                                        className="px-4 py-3 hover:bg-gray-50 text-gray-600 transition-colors"
                                    >
                                        <Minus className="h-5 w-5" />
                                    </button>
                                    <span className="px-4 py-3 font-bold text-gray-900 min-w-[50px] text-center">{quantity}</span>
                                    <button
                                        onClick={() => setQuantity(quantity + 1)}
                                        className="px-4 py-3 hover:bg-gray-50 text-gray-600 transition-colors"
                                    >
                                        <Plus className="h-5 w-5" />
                                    </button>
                                </div>

                                <Button
                                    className="flex-1 py-4 text-base md:text-lg rounded-xl shadow-xl shadow-primary/20 hover:shadow-primary/40 active:scale-95 transition-all h-auto"
                                    onClick={handleAddToCart}
                                    disabled={product.stock === 0}
                                >
                                    <ShoppingCart className="mr-2 h-5 w-5" />
                                    {product.stock === 0 ? 'Out of Stock' : `Add to Cart - ₹${product.price * quantity}`}
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </MainLayout>
    );
}

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuthStore } from '../store/useAuthStore';
import { useToast } from '../context/ToastContext';
import { Store, User, Mail, Lock, ArrowRight, Loader2, Truck, Phone } from 'lucide-react';
import api from '../lib/api';

export const RegisterPage = () => {
    const navigate = useNavigate();
    const { login } = useAuthStore();
    const { addToast } = useToast();

    const [formData, setFormData] = useState({
        name: '',
        email: '',
        phone: '',
        password: '',
        confirmPassword: '',
        role: 'buyer'
    });
    const [isLoading, setIsLoading] = useState(false);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData(prev => ({
            ...prev,
            [e.target.name]: e.target.value
        }));
    };

    const handleRoleSelect = (role: string) => {
        setFormData(prev => ({ ...prev, role }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (formData.password !== formData.confirmPassword) {
            addToast("Passwords don't match", 'error');
            return;
        }

        setIsLoading(true);

        try {
            const response = await api.post('/auth/register', {
                name: formData.name,
                email: formData.email,
                phone: formData.phone,
                password: formData.password,
                // @ts-ignore
                shopName: formData.shopName,
                role: formData.role
            });

            const data = response.data;

            login(data.user, data.token);
            addToast('Welcome to Vemgal Mart!', 'success');

            if (data.user.role === 'seller') navigate('/seller');
            else if (data.user.role === 'delivery_man') navigate('/delivery');
            else navigate('/');

        } catch (error: any) {
            addToast(error.response?.data?.message || error.message, 'error');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex bg-white">
            {/* Right Side (on large screens) - Form */}
            <div className="w-full lg:w-1/2 flex flex-col justify-center px-4 sm:px-12 lg:px-24 py-12 order-last lg:order-first">
                <div className="sm:mx-auto sm:w-full sm:max-w-md">
                    <Link to="/" className="flex items-center gap-2 mb-8 group">
                        <div className="h-10 w-10 bg-primary/10 rounded-xl flex items-center justify-center group-hover:bg-primary/20 transition-colors">
                            <Store className="h-6 w-6 text-primary" />
                        </div>
                        <span className="text-xl font-bold text-gray-900">Vemgal Mart</span>
                    </Link>

                    <h2 className="text-3xl font-bold tracking-tight text-gray-900">
                        Create your account
                    </h2>
                    <p className="mt-2 text-sm text-gray-600">
                        Already have an account?{' '}
                        <Link to="/login" className="font-semibold text-primary hover:text-primary-dark transition-colors">
                            Sign in instead
                        </Link>
                    </p>
                </div>

                <div className="mt-10 sm:mx-auto sm:w-full sm:max-w-md">
                    <form className="space-y-5" onSubmit={handleSubmit}>
                        {/* Role Selection Cards */}
                        <div className="grid grid-cols-3 gap-3 mb-6">
                            {[
                                { id: 'buyer', icon: User, label: 'Buyer' },
                                { id: 'seller', icon: Store, label: 'Seller' },
                                { id: 'delivery_man', icon: Truck, label: 'Delivery' }
                            ].map((role) => (
                                <button
                                    type="button"
                                    key={role.id}
                                    onClick={() => handleRoleSelect(role.id)}
                                    className={`flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all ${formData.role === role.id
                                        ? 'border-primary bg-primary/5 text-primary'
                                        : 'border-gray-100 bg-white text-gray-500 hover:border-gray-200 hover:bg-gray-50'
                                        }`}
                                >
                                    <role.icon className={`h-6 w-6 mb-1 ${formData.role === role.id ? 'text-primary' : 'text-gray-400'}`} />
                                    <span className="text-xs font-semibold">{role.label}</span>
                                </button>
                            ))}
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700">Full Name</label>
                            <div className="mt-1 relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <User className="h-5 w-5 text-gray-400" />
                                </div>
                                <input
                                    name="name"
                                    type="text"
                                    required
                                    className="block w-full pl-10 pr-3 py-3 border border-gray-200 rounded-xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-gray-50 focus:bg-white"
                                    placeholder="John Doe"
                                    value={formData.name}
                                    onChange={handleChange}
                                />
                            </div>
                        </div>

                        {formData.role === 'seller' && (
                            <div>
                                <label className="block text-sm font-medium text-gray-700">Shop Name</label>
                                <div className="mt-1 relative">
                                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                        <Store className="h-5 w-5 text-gray-400" />
                                    </div>
                                    <input
                                        name="shopName"
                                        type="text"
                                        required
                                        className="block w-full pl-10 pr-3 py-3 border border-gray-200 rounded-xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-gray-50 focus:bg-white"
                                        placeholder="My Super Store"
                                        // @ts-ignore
                                        value={formData.shopName || ''}
                                        onChange={handleChange}
                                    />
                                </div>
                            </div>
                        )}

                        <div>
                            <label className="block text-sm font-medium text-gray-700">Email address</label>
                            <div className="mt-1 relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <Mail className="h-5 w-5 text-gray-400" />
                                </div>
                                <input
                                    name="email"
                                    type="email"
                                    required
                                    className="block w-full pl-10 pr-3 py-3 border border-gray-200 rounded-xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-gray-50 focus:bg-white"
                                    placeholder="you@example.com"
                                    value={formData.email}
                                    onChange={handleChange}
                                />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700">Phone Member</label>
                            <div className="mt-1 relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <Phone className="h-5 w-5 text-gray-400" />
                                </div>
                                <input
                                    name="phone"
                                    type="tel"
                                    required
                                    className="block w-full pl-10 pr-3 py-3 border border-gray-200 rounded-xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-gray-50 focus:bg-white"
                                    placeholder="+91 98765 43210"
                                    value={formData.phone}
                                    onChange={handleChange}
                                />
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                            <div>
                                <label className="block text-sm font-medium text-gray-700">Password</label>
                                <div className="mt-1 relative">
                                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                        <Lock className="h-5 w-5 text-gray-400" />
                                    </div>
                                    <input
                                        name="password"
                                        type="password"
                                        required
                                        className="block w-full pl-10 pr-3 py-3 border border-gray-200 rounded-xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-gray-50 focus:bg-white"
                                        placeholder="••••••••"
                                        value={formData.password}
                                        onChange={handleChange}
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700">Confirm</label>
                                <div className="mt-1 relative">
                                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                        <Lock className="h-5 w-5 text-gray-400" />
                                    </div>
                                    <input
                                        name="confirmPassword"
                                        type="password"
                                        required
                                        className="block w-full pl-10 pr-3 py-3 border border-gray-200 rounded-xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-gray-50 focus:bg-white"
                                        placeholder="••••••••"
                                        value={formData.confirmPassword}
                                        onChange={handleChange}
                                    />
                                </div>
                            </div>
                        </div>

                        <div className="pt-2">
                            <button
                                type="submit"
                                disabled={isLoading}
                                className={`w-full flex justify-center items-center gap-2 py-3 px-4 border border-transparent rounded-xl shadow-sm text-sm font-semibold text-white bg-primary hover:bg-primary-dark focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-all ${isLoading ? 'opacity-70 cursor-not-allowed' : 'hover:shadow-lg hover:shadow-primary/30'}`}
                            >
                                {isLoading ? (
                                    <>
                                        <Loader2 className="h-4 w-4 animate-spin" />
                                        Creating Account...
                                    </>
                                ) : (
                                    <>
                                        Get Started <ArrowRight className="h-4 w-4" />
                                    </>
                                )}
                            </button>
                        </div>
                    </form>

                    <p className="mt-6 text-center text-xs text-gray-500">
                        By signing up, you agree to our{' '}
                        <a href="#" className="font-medium text-gray-900 hover:underline">Terms of Service</a>{' '}
                        and{' '}
                        <a href="#" className="font-medium text-gray-900 hover:underline">Privacy Policy</a>.
                    </p>
                </div>
            </div>

            {/* Left Side (on large screens) - Image */}
            <div className="hidden lg:block lg:w-1/2 relative bg-gray-900 order-first lg:order-last">
                <div className="absolute inset-0 bg-gradient-to-bl from-primary/40 to-black/60 z-10" />
                <img
                    className="absolute inset-0 h-full w-full object-cover opacity-80"
                    src="https://images.unsplash.com/photo-1542838132-92c53300491e?q=80&w=1974&auto=format&fit=crop"
                    alt="Grocery Shopping"
                />
                <div className="relative z-20 h-full flex flex-col justify-end p-12 text-white">
                    <h3 className="text-4xl font-bold mb-4">Join the family.</h3>
                    <p className="text-lg text-gray-200 max-w-md">
                        Whether you're buying, selling, or delivering, Vemgal Mart connects you to your community.
                    </p>
                </div>
            </div>
        </div>
    );
};

import { useState, useEffect } from 'react';
import { useStore } from '../store/useStore';
import { useSocket } from '../hooks/useSocket';
import { useToast } from '../context/ToastContext';
import { MainLayout } from '../components/layout/MainLayout';
import { AddProductForm } from '../components/seller/AddProductForm';
import { SellerAnalytics } from '../components/seller/SellerAnalytics';
import { Badge } from '../components/ui/Badge';
import { CheckCircle, LayoutDashboard, Package, ShoppingBag } from 'lucide-react';
import { Button } from '../components/ui/Button';
import api from '../lib/api';

import { useAuthStore } from '../store/useAuthStore';

export function SellerDashboard() {
    const { products, orders, updateOrderStatus, setOrders } = useStore();
    const { user } = useAuthStore();
    const [activeTab, setActiveTab] = useState<'overview' | 'products' | 'orders'>('overview');
    const socket = useSocket();
    const { addToast } = useToast();

    const fetchOrders = async () => {
        try {
            const response = await api.get('/orders/my-orders');
            setOrders(response.data);
        } catch (error) {
            console.error('Failed to fetch orders', error);
        }
    };

    useEffect(() => {
        fetchOrders();

        if (socket) {
            socket.on('new_order', (order: any) => {
                addToast(`New order received! #${order.id}`, 'success');
                fetchOrders();
            });

            socket.on('order_status_updated', () => {
                fetchOrders();
            });
        }

        return () => {
            if (socket) {
                socket.off('new_order');
                socket.off('order_status_updated');
            }
        };
    }, [socket, addToast]);

    // Filter products by current seller
    const myProducts = products.filter(p => p.sellerId === user?.id);

    // Filter pending orders
    const pendingOrders = orders.filter(o => o.status === 'pending' || o.status === 'preparing');

    return (
        <MainLayout>
            <div className="container mx-auto px-4 py-8">
                <div className="mb-10 flex flex-col md:flex-row md:items-end justify-between gap-4">
                    <div>
                        <h1 className="text-4xl font-extrabold text-gray-900 tracking-tight">Seller Dashboard</h1>
                        <p className="mt-2 text-lg text-gray-600">Manage your business, <span className="font-semibold text-primary">{user?.name}</span>.</p>
                    </div>
                    <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm">
                        {[
                            { id: 'overview', label: 'Overview', icon: LayoutDashboard },
                            { id: 'products', label: 'Products', icon: Package },
                            { id: 'orders', label: 'Orders', icon: ShoppingBag },
                        ].map((tab) => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id as any)}
                                className={`flex items-center gap-2 px-6 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === tab.id
                                    ? 'bg-primary text-white shadow-lg shadow-primary/25'
                                    : 'text-gray-500 hover:text-gray-900 hover:bg-gray-50'
                                    }`}
                            >
                                <tab.icon className="h-4 w-4" />
                                {tab.label}
                            </button>
                        ))}
                    </div>
                </div>

                {activeTab === 'overview' && (
                    <div className="space-y-8 animate-fade-in">
                        <SellerAnalytics />
                    </div>
                )}

                {activeTab === 'products' && (
                    <div className="grid grid-cols-1 gap-8 lg:grid-cols-12 animate-fade-in">
                        <div className="lg:col-span-12">
                            <div className="rounded-3xl border border-gray-100 bg-white p-6 md:p-8 shadow-xl shadow-gray-200/50 mb-8">
                                <h2 className="mb-6 text-2xl font-bold text-gray-900">Add New Product</h2>
                                <AddProductForm />
                            </div>
                            <div className="rounded-3xl border border-gray-100 bg-white p-6 md:p-8 shadow-xl shadow-gray-200/50">
                                <div className="mb-6 flex items-center justify-between">
                                    <h2 className="text-2xl font-bold text-gray-900">My Inventory ({myProducts.length})</h2>
                                </div>

                                {myProducts.length === 0 ? (
                                    <div className="text-center py-10">
                                        <p className="text-gray-500">You haven't added any products yet.</p>
                                    </div>
                                ) : (
                                    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
                                        {myProducts.map(product => (
                                            <div key={product.id} className="group relative flex flex-col rounded-2xl border border-gray-100 bg-white p-4 transition-all hover:shadow-lg hover:shadow-gray-200/50 hover:border-gray-200">
                                                <div className="flex gap-4 mb-4">
                                                    <div className="h-20 w-20 rounded-xl bg-gray-100 overflow-hidden shrink-0">
                                                        <img src={product.image} alt={product.name} className="h-full w-full object-cover" />
                                                    </div>
                                                    <div className="min-w-0 flex-1">
                                                        <h3 className="font-bold text-gray-900 line-clamp-1">{product.name}</h3>
                                                        <p className="text-sm font-medium text-primary mt-1">₹{product.price}</p>
                                                        <div className="flex items-center gap-2 mt-1">
                                                            <span className={`text-[10px] items-center px-1.5 py-0.5 rounded-md font-medium border ${product.stock && product.stock > 0
                                                                ? 'bg-green-50 text-green-700 border-green-100'
                                                                : 'bg-red-50 text-red-700 border-red-100'
                                                                }`}>
                                                                {product.stock && product.stock > 0 ? `Stock: ${product.stock}` : 'Out of Stock'}
                                                            </span>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div className="flex gap-2 mt-auto pt-4 border-t border-gray-50">
                                                    <Button
                                                        variant="outline"
                                                        className="flex-1 py-2 text-xs border-gray-200"
                                                        onClick={() => addToast('Edit functionality coming soon!', 'info')}
                                                    >
                                                        Edit
                                                    </Button>
                                                    <Button
                                                        variant="ghost"
                                                        className="flex-1 py-2 text-xs text-red-600 hover:bg-red-50 hover:text-red-700"
                                                        onClick={async () => {
                                                            if (confirm('Are you sure you want to delete this product?')) {
                                                                try {
                                                                    const { deleteProduct } = useStore.getState();
                                                                    await deleteProduct(product.id);
                                                                    addToast('Product deleted successfully', 'success');
                                                                } catch (err) {
                                                                    addToast('Failed to delete product', 'error');
                                                                }
                                                            }
                                                        }}
                                                    >
                                                        Delete
                                                    </Button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'orders' && (
                    <div className="animate-fade-in">
                        <div className="rounded-3xl border border-gray-100 bg-white p-6 md:p-8 shadow-xl shadow-gray-200/50">
                            <div className="mb-8 flex items-center justify-between">
                                <h2 className="text-xl font-bold text-gray-900">Incoming Orders</h2>
                                <Badge variant="warning" className="rounded-full px-3">{pendingOrders.length} Pending</Badge>
                            </div>

                            {pendingOrders.length === 0 ? (
                                <div className="py-20 text-center">
                                    <div className="mx-auto mb-6 flex h-20 w-20 items-center justify-center rounded-full bg-gray-50">
                                        <CheckCircle className="h-10 w-10 text-gray-300" />
                                    </div>
                                    <h3 className="text-lg font-bold text-gray-900 mb-2">All caught up!</h3>
                                    <p className="text-gray-500">No new orders at the moment.</p>
                                </div>
                            ) : (
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                    {pendingOrders.map(order => (
                                        <div key={order.id} className="rounded-3xl border border-gray-100 bg-gray-50/50 p-6 transition-all hover:bg-white hover:shadow-xl hover:shadow-gray-200/50 hover:border-gray-200">
                                            <div className="mb-4 flex items-center justify-between">
                                                <span className="font-bold text-gray-900 bg-white px-3 py-1 rounded-lg border border-gray-100 shadow-sm">#{order.id}</span>
                                                <span className="text-xs font-bold px-2 py-1 rounded-full bg-yellow-100 text-yellow-700 uppercase tracking-wider">
                                                    {order.status.replace('_', ' ')}
                                                </span>
                                            </div>
                                            <div className="mb-6">
                                                <p className="text-sm text-gray-500 mb-2">Customer: <span className="font-semibold text-gray-900">{order.customerName}</span></p>
                                                <div className="space-y-2">
                                                    {order.items.map(item => (
                                                        <div key={item.id} className="flex justify-between text-sm">
                                                            <span className="text-gray-600">{item.name} <span className="text-gray-400">x{item.quantity}</span></span>
                                                        </div>
                                                    ))}
                                                </div>
                                                <div className="mt-4 pt-4 border-t border-gray-200/50 flex justify-between items-center text-sm font-semibold">
                                                    <span>Total Earnings</span>
                                                    <span className="text-green-600 text-base">₹{order.total}</span>
                                                </div>
                                            </div>
                                            <Button
                                                className="w-full gap-2 rounded-xl py-3 shadow-lg shadow-primary/20"
                                                onClick={() => updateOrderStatus(order.id, 'ready_for_pickup')}
                                            >
                                                <CheckCircle className="h-5 w-5" />
                                                Mark Ready
                                            </Button>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </MainLayout >
    );
}

import { create } from 'zustand';
import type { Product, CartItem, Order, User, Banner } from '../types';

interface StoreState {
    user: User | null;
    banners: Banner[];
    products: Product[];
    cart: CartItem[];
    orders: Order[];
    searchQuery: string;
    selectedCategory: string | null;

    // Actions
    setSearchQuery: (query: string) => void;
    setSelectedCategory: (category: string | null) => void;
    setOrders: (orders: Order[]) => void;
    fetchBanners: () => Promise<void>;
    fetchProducts: () => Promise<void>;
    fetchCart: () => Promise<void>;
    addProduct: (productData: any) => Promise<Product>;
    deleteProduct: (productId: string) => Promise<void>;
    addToCart: (product: Product) => Promise<void>;
    removeFromCart: (productId: string) => Promise<void>;
    updateCartQuantity: (productId: string, quantity: number) => Promise<void>;
    clearCart: () => Promise<void>;
    placeOrder: (order: Order) => void;
    updateOrderStatus: (orderId: string, status: string) => Promise<void>;
    assignDeliveryMan: (orderId: string, deliveryManId: string) => Promise<void>;
    reset: () => void;
}

// Mock Data removed

export const useStore = create<StoreState>((set, get) => ({
    user: null, // Managed by useAuthStore
    banners: [],
    products: [],
    cart: [],
    orders: [],
    searchQuery: '',
    selectedCategory: null,

    setSearchQuery: (query) => set({ searchQuery: query }),
    setSelectedCategory: (category) => set({ selectedCategory: category }),
    setOrders: (orders) => set({ orders }),

    fetchBanners: async () => {
        try {
            // If we have a banner endpoint, use it. Otherwise, defaults to empty []
            // const response = await import('../lib/api').then(m => m.default.get('/banners'));
            // set({ banners: response.data });
            // For now, since we cleared DB, banners are empty. 
            // We can fetch from '/banners' if implemented.
            // Let's assume there is a /banners endpoint based on file existence.
            const response = await import('../lib/api').then(m => m.default.get('/banners'));
            set({ banners: response.data });
        } catch (error) {
            console.error('Failed to fetch banners:', error);
            // Fallback to empty if fails
            set({ banners: [] });
        }
    },

    fetchProducts: async () => {
        try {
            const response = await import('../lib/api').then(m => m.default.get('/products'));
            set({ products: response.data });
        } catch (error) {
            console.error('Failed to fetch products:', error);
        }
    },

    addProduct: async (productData: any) => {
        try {
            const response = await import('../lib/api').then(m => m.default.post('/products', productData));
            set((state) => ({ products: [...state.products, response.data.product] }));
            return response.data.product;
        } catch (error) {
            console.error('Failed to add product:', error);
            throw error;
        }
    },

    deleteProduct: async (productId: string) => {
        try {
            await import('../lib/api').then(m => m.default.delete(`/products/${productId}`));
            set((state) => ({
                products: state.products.filter(p => p.id !== productId)
            }));
        } catch (error) {
            console.error('Failed to delete product:', error);
            throw error;
        }
    },

    fetchCart: async () => {
        try {
            const response = await import('../lib/api').then(m => m.default.get('/cart'));
            if (response.data && response.data.items) {
                const mappedCart = response.data.items.map((item: any) => ({
                    ...item.product,
                    quantity: item.quantity,
                    cartItemId: item.id
                }));
                set({ cart: mappedCart });
            }
        } catch (error) {
            console.error('Failed to fetch cart:', error);
        }
    },

    addToCart: async (product) => {
        try {
            // Optimistic update
            // const state = get();
            // We can't easily optimistic update 'cartItemId' for new items, so we rely on fetchCart after.

            await import('../lib/api').then(m => m.default.post('/cart/add', {
                productId: product.id,
                quantity: 1
            }));

            // Refresh cart to get the correct state and IDs
            await get().fetchCart();
        } catch (error) {
            console.error('Failed to add to cart:', error);
        }
    },

    removeFromCart: async (productId) => {
        try {
            const state = get();
            const item = state.cart.find(i => i.id === productId);
            if (!item?.cartItemId) return;

            await import('../lib/api').then(m => m.default.delete(`/cart/item/${item.cartItemId}`));

            set((state) => ({
                cart: state.cart.filter(item => item.id !== productId)
            }));
        } catch (error) {
            console.error('Failed to remove from cart:', error);
        }
    },

    updateCartQuantity: async (productId, quantity) => {
        try {
            const state = get();
            const item = state.cart.find(i => i.id === productId);
            if (!item?.cartItemId) return;

            if (quantity <= 0) {
                await get().removeFromCart(productId);
                return;
            }

            await import('../lib/api').then(m => m.default.put(`/cart/item/${item.cartItemId}`, { quantity }));

            // Optimistic update for UI responsiveness
            set((state) => ({
                cart: state.cart.map(item =>
                    item.id === productId ? { ...item, quantity } : item
                )
            }));
        } catch (error) {
            console.error('Failed to update cart quantity:', error);
            // Rollback could be added here
        }
    },

    clearCart: async () => {
        try {
            await import('../lib/api').then(m => m.default.delete('/cart/clear'));
            set({ cart: [] });
        } catch (error) {
            console.error('Failed to clear cart:', error);
        }
    },

    placeOrder: (order) => set((state) => ({
        orders: [order, ...state.orders],
        cart: []
    })),

    updateOrderStatus: async (orderId, status) => {
        try {
            await import('../lib/api').then(m => m.default.put(`/orders/${orderId}/status`, { status }));
            set((state) => ({
                orders: state.orders.map(o => o.id === orderId ? { ...o, status: status as Order['status'] } : o)
            }));
        } catch (error) {
            console.error('Failed to update order status:', error);
        }
    },

    assignDeliveryMan: async (orderId, deliveryManId) => {
        try {
            await import('../lib/api').then(m => m.default.put(`/orders/${orderId}/assign`));
            set((state) => ({
                orders: state.orders.map(o => o.id === orderId ? { ...o, deliveryManId, status: 'preparing' } : o)
            }));
        } catch (error) {
            console.error('Failed to assign delivery man:', error);
        }
    },

    reset: () => set({ cart: [], orders: [], user: null, searchQuery: '' })
}));
